inline constexpr char kDefaultIni[] = R"rwrini(; Red Wolf Radio settings. Republic Mod Loader opens this file from the plugin page.
; Changes take effect on the next game launch.
; Настройки Red Wolf Radio. Republic Mod Loader открывает этот файл со страницы плагина.
; Изменения вступают в силу после перезапуска игры. Имена ключей не переводите.

[RedWolfRadio]
SchemaVersion=1

[Sources]
ExternalEnabled=true
; Включить музыку из внешней папки: true — да, false — нет.
; Environment variables such as %USERPROFILE% are expanded.
; Leave blank to use this Windows account's configured Music known folder.
; %USERPROFILE% заменяется папкой текущего пользователя Windows.
; Пустое значение использует системную папку «Музыка», включая перенаправление.
ExternalPath=%USERPROFILE%\Music
ExternalRecursive=true
; true — сканировать вложенные папки; false — только указанную папку.
; The optional local folder is Music beside RedWolfRadio.dll.
; Дополнительная локальная папка Music находится рядом с RedWolfRadio.dll.
PluginLocalEnabled=false
PluginLocalRecursive=true

[Cache]
; Maximum derived-audio cache size in MiB. Zero means unlimited.
; Лимит кэша в МиБ; 0 — без ограничения. Защищённые треки могут превысить лимит.
MaxSizeMiB=4096
; Number of upcoming playlist entries kept ready.
; Количество следующих треков, подготовленных заранее.
PrefetchTracks=5
; Keep this many previous tracks ready in the same cache (0-64).
; Количество предыдущих треков, сохраняемых готовыми в кэше (0–64).
HistoryTracks=3

[Hotkeys]
; Active during gameplay while the game is focused. None disables a binding.
; Работают в загруженной республике, когда окно игры активно. None отключает сочетание.
Enabled=true
Next=Ctrl+Shift+Right
; One press restarts; further presses within one second go backward.
; Одно нажатие — с начала; повторное в течение секунды — предыдущий трек.
Previous=Ctrl+Shift+Left
PlayPause=Ctrl+Shift+Down

[Display]
; Optional 5-second title on the HUD; off by default when using the movable player.
; Необязательное имя трека на экране на 5 секунд; по умолчанию выключено.
ShowTrackName=false
; Enable the movable player opened from Scripts (0101). Requires the packaged script.
; Включить перемещаемый плеер в меню скриптов (0101). Нужен скрипт из комплекта.
; Updates automatically; closing the window does not stop music.
; Имя обновляется автоматически; закрытие окна не останавливает музыку.
NativeSongPopup=true
; Language of the HUD and player: en (English) or ru (Russian).
; Язык надписи и плеера: en — английский, ru — русский.
Language=en

[Originals]
; Mode may be all, selected, or none.
; all — все оригинальные треки; selected — кроме исключённых; none — без оригинальных треков.
Mode=all
; With Mode=selected, list stable original: IDs separated by commas.
; При selected укажите ID original: из журнала RML через запятую.
ExcludedIds=
)rwrini";
